python -c 'import re; from collections import defaultdict; import numpy as np; import pandas as pd
D=pd.read_csv("/work/b3_supercon_data.csv")
A="O Cu Ba Sr Y Ca La Bi Fe Nb C Pr As B Pb Ce Mo V Zn Ni".split()
B=np.array([.697674,.454545,.333333,.285714,.4,.272727,.78,.521978,.502513,.98,.972,.265043,.5,1.,.5,.28,1.,.9918,1.,.6])
def parse(f):
 t=re.findall(r"([A-Z][a-z]?)([0-9]*\.?[0-9]*)",f); assert "".join(a+b for a,b in t)==f
 v=defaultdict(float)
 for a,b in t: v[a]+=float(b) if b else 1.
 s=sum(v.values()); return {a:b/s for a,b in v.items()}
P=[parse(f) for f in D.composition]; E=A+sorted(set().union(*P)-set(A)); X=np.array([[p.get(e,0.) for e in E] for p in P]); Y=D.target.to_numpy(); ok=np.all(X[:,20:]==0,axis=1); G=np.unique(np.round(X,10),axis=0,return_inverse=True)[1]
print("Rows",len(D),"elements",len(E),"allowed-only",ok.sum()); print("Missing",D.isna().sum().to_dict())
for j,e in enumerate(A): print(e,"observed range",X[:,j].min(),X[:,j].max(),"given max",B[j])
print("TOP ALLOWED"); print(D.loc[ok].nlargest(25,"target").to_string(index=False))
print("DUPLICATES")
for g in np.unique(G):
 ids=np.flatnonzero(G==g)
 if len(ids)>1: print(D.iloc[ids].to_string(index=False))
print("NEAREST NEIGHBORS")
for i in D.loc[ok].nlargest(7,"target").index:
 d=np.linalg.norm(X-X[i],axis=1); ids=np.argsort(d)[:9]; R=D.iloc[ids].copy(); R["distance"]=d[ids]; R["allowed"]=ok[ids]; print("\nCenter",D.composition[i],Y[i]); print(R.to_string(index=False))'

python -c 'import re; from collections import defaultdict; import numpy as np; import pandas as pd; from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor; from sklearn.neighbors import KNeighborsRegressor; from sklearn.model_selection import GroupKFold,cross_val_predict; from sklearn.metrics import mean_absolute_error,mean_squared_error
